def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def _info(t):
    """Adds parent[k] (-1 for the root) and depth[k]. Parents come before children in level order."""
    vals, left, right = _links(t)
    n = len(vals)
    par = [-1] * n
    depth = [0] * n
    for k in range(n):
        for c in (left[k], right[k]):
            if c != -1:
                par[c] = k
                depth[c] = depth[k] + 1
    return vals, left, right, par, depth


def countLeafPairs(tree, distance):
    vals, left, right = _links(tree)
    n = len(vals)
    D = distance
    cnt = [None] * n
    pairs = 0
    for k in range(n - 1, -1, -1):
        l, r = left[k], right[k]
        if l == -1 and r == -1:
            c = [0] * (D + 1)
            c[0] = 1
            cnt[k] = c
            continue
        A = [0] * (D + 1)
        B = [0] * (D + 1)
        if l != -1:
            A[1:] = cnt[l][:D]
            cnt[l] = None
        if r != -1:
            B[1:] = cnt[r][:D]
            cnt[r] = None
        if l != -1 and r != -1:
            for a in range(1, D + 1):
                if A[a]:
                    for b in range(1, D - a + 1):
                        pairs += A[a] * B[b]
        cnt[k] = [A[i] + B[i] for i in range(D + 1)]
    return pairs
